// Some portions generated by Codex
import { encodeWorkspace, WORKSPACE_FORMAT } from "./workspace-format.ts";
import { MAX_WORKSPACE_BYTES, parseWorkspacePayload, type WorkspacePayload } from "./workspace.ts";
import { INTERNAL_SCOPED_BNODE_NODE_PREFIX, blankNodeDocumentScope, sparqlNodeId, sparqlTermFromNodeId } from "./rdf-terms.ts";

/** Server digests contain no server URL, credentials, or browser connection/session identifiers. */
export type WorkspaceSnapshotSource = { basePath: string; serverIdentity: string; repositoryId: string };
export type ParsedWorkspaceSnapshot = {
  name: string;
  source: WorkspaceSnapshotSource | null;
  payload: WorkspacePayload;
  sameSource: boolean;
};
const SNAPSHOT_FORMAT = "rdf4j-graph-workspace";
const SNAPSHOT_VERSION = 1;
const SERVER_DIGEST = /^sha256:[a-f0-9]{64}(?::.*)?$/;

export function workspaceSnapshotSource(basePath: string, repositoryId: string, serverIdentity: string): WorkspaceSnapshotSource {
  if (typeof basePath !== "string" || (basePath !== "" && (!/^\/[^?#\\\u0000-\u0020]*$/.test(basePath) || basePath.startsWith("//"))) ||
    typeof repositoryId !== "string" || !repositoryId ||
    typeof serverIdentity !== "string" || !SERVER_DIGEST.test(serverIdentity)) {
    throw new Error("The repository server identity is unavailable or invalid.");
  }
  return { basePath: basePath.replace(/\/+$/, ""), repositoryId, serverIdentity: serverIdentity.split(":").slice(0, 2).join(":") };
}

export function snapshotName(name: string): string {
  if (typeof name !== "string" || !name.trim() || name.trim().length > 256) {
    throw new Error("Enter a workspace name of 1–256 characters.");
  }
  return name.trim();
}

function bounded(raw: string) {
  if (typeof raw !== "string" || raw.length > MAX_WORKSPACE_BYTES || new TextEncoder().encode(raw).byteLength > MAX_WORKSPACE_BYTES) {
    throw new Error("The workspace is too large: the file limit is 64 MB.");
  }
}

/** Validate the entire snapshot. Explicit saves never use the lossy autosave fitting/recovery path. */
export function prepareWorkspaceSnapshot(payload: WorkspacePayload): string {
  let raw: string;
  try {
    validateNodeTerms(payload);
    // Compare the entire decoded form: malformed values must never quietly disappear in an explicit save.
    const plain = JSON.stringify({ ...payload, graph: { ...payload.graph, nodes: payload.graph.nodes.map(node => {
      // The runtime declares this repository lookup flag as a cache, not part of a workspace (graph-types.ts).
      const { typesLookedUp: _cache, ...stored } = node as typeof node & { typesLookedUp?: boolean };
      return stored;
    }) } });
    raw = encodeWorkspace(payload, { exactPositions: true });
    const validated = parseWorkspacePayload(raw, { repositoryReferences: true });
    if (!validated || JSON.stringify(validated) !== JSON.stringify(JSON.parse(plain))) {
      // Key order is immaterial. The parsed form supplies defaults only for old files, not explicit new saves.
      if (!validated || !sameValue(validated, JSON.parse(plain))) throw new Error("Invalid workspace content.");
    }
  } catch (error) {
    throw new Error(`The complete workspace cannot be saved: ${error instanceof Error ? error.message : "invalid content"}`);
  }
  bounded(raw);
  return raw;
}

function validateNodeTerms(payload: WorkspacePayload) {
  for (const node of payload.graph.nodes) {
    if (node.kind === "iri") continue;
    const term = sparqlTermFromNodeId(node.id);
    if (!term || (node.kind === "blank" ? term.type !== "bnode" : term.type !== "literal" && term.type !== "typed-literal")) {
      throw new Error("Invalid graph term identity.");
    }
  }
}

/** Plain object equality without key-order dependence; arrays retain their order. */
function sameValue(left: unknown, right: unknown): boolean {
  if (left === right) return true;
  if (!left || !right || typeof left !== "object" || typeof right !== "object" || Array.isArray(left) !== Array.isArray(right)) return false;
  const a = left as Record<string, unknown>, b = right as Record<string, unknown>;
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every(key => Object.hasOwn(b, key) && sameValue(a[key], b[key]));
}

/** Provenance is explanatory text, never a destination to reconnect to. Remove URL credentials and query secrets. */
function portableEndpoint(value: string) {
  try {
    const relative = value.startsWith("//"), url = new URL(relative ? `https:${value}` : value);
    url.username = ""; url.password = ""; url.search = ""; url.hash = "";
    return relative ? `//${url.host}${url.pathname}` : url.toString();
  } catch {
    return value.split(/[?#]/, 1)[0];
  }
}

/** One versioned file envelope containing the compact workspace and its stable source identity. */
export function encodeWorkspaceSnapshot(name: string, source: WorkspaceSnapshotSource, payload: WorkspacePayload): string {
  const stable = workspaceSnapshotSource(source.basePath, source.repositoryId, source.serverIdentity);
  // An endpoint URL is not a portable connection setting. The active page keeps its own repository connection.
  const portable = { ...payload, customUrl: "", provenanceBatches: payload.provenanceBatches.map(batch =>
    ({ ...batch, endpoint: portableEndpoint(batch.endpoint) })) };
  const workspace = JSON.parse(prepareWorkspaceSnapshot(portable));
  const raw = JSON.stringify({ format: SNAPSHOT_FORMAT, version: SNAPSHOT_VERSION, name: snapshotName(name), source: stable,
    workspaceVersion: WORKSPACE_FORMAT, workspace });
  bounded(raw);
  return raw;
}

function parsedSource(value: unknown): WorkspaceSnapshotSource | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const source = value as Record<string, unknown>;
  if (typeof source.basePath !== "string" || typeof source.repositoryId !== "string" || typeof source.serverIdentity !== "string") return null;
  try { return workspaceSnapshotSource(source.basePath, source.repositoryId, source.serverIdentity); } catch { return null; }
}

/** Import-only blank identities belong to this file, including references whose cards are not materialized yet. */
function documentScoped(payload: WorkspacePayload): WorkspacePayload {
  const document = blankNodeDocumentScope(), references = new Map<string, string>();
  const migrate = (id: string): string => {
    const known = references.get(id);
    if (known) return known;
    const term = sparqlTermFromNodeId(id);
    if (!term && id.startsWith(INTERNAL_SCOPED_BNODE_NODE_PREFIX)) throw new Error("Invalid blank-node identity in the workspace.");
    if (term?.type !== "bnode") return id;
    const namespace = term["rdf4j:reference"] ? ["repository"] : term["rdf4j:scope"] !== undefined ? ["document", term["rdf4j:scope"]] : ["legacy"];
    const mapped = sparqlNodeId({ type: "bnode", value: term.value, "rdf4j:scope": JSON.stringify([document, ...namespace]) });
    references.set(id, mapped); return mapped;
  };
  const edgeIds = new Map<string, string>();
  const nodes = payload.graph.nodes.map(node => ({ ...node, id: migrate(node.id) }));
  const edges = payload.graph.edges.map(edge => {
    const source = migrate(edge.source), target = migrate(edge.target);
    const id = edge.id === JSON.stringify([edge.source, edge.predicate, edge.target]) ? JSON.stringify([source, edge.predicate, target]) : edge.id;
    edgeIds.set(edge.id, id); return { ...edge, id, source, target };
  });
  const statementLinks = payload.graph.statementLinks?.map(link => {
    const source = migrate(link.source), subject = migrate(link.subject), object = migrate(link.object);
    const id = link.id === JSON.stringify([link.source, link.predicate, link.subject, link.statementPredicate, link.object])
      ? JSON.stringify([source, link.predicate, subject, link.statementPredicate, object]) : link.id;
    const statementEdgeId = edgeIds.get(link.statementEdgeId) ??
      (link.statementEdgeId === JSON.stringify([link.subject, link.statementPredicate, link.object])
        ? JSON.stringify([subject, link.statementPredicate, object]) : link.statementEdgeId);
    return { ...link, id, source, subject, object, statementEdgeId };
  });
  return { ...payload, graph: { ...payload.graph, nodes, edges, ...(statementLinks ? { statementLinks } : {}) },
    selectedNodeIds: payload.selectedNodeIds.map(migrate), focusedNodeId: payload.focusedNodeId === null ? null : migrate(payload.focusedNodeId),
    namedGroups: payload.namedGroups.map(group => ({ ...group, nodeIds: group.nodeIds.map(migrate) })),
    // A foreign blank graph name cannot designate a graph in the active repository.
    ...(payload.scope && sparqlTermFromNodeId(payload.scope)?.type === "bnode" ? { scope: "default" } : {}),
    ...(payload.view ? { view: { ...payload.view,
      selectedFacetValues: payload.view.selectedFacetValues.map(([facet, values]) => [facet, values.map(migrate)]),
      focusedEdgeId: payload.view.focusedEdgeId === null ? null : edgeIds.get(payload.view.focusedEdgeId) ?? payload.view.focusedEdgeId } } : {}) };
}

export function parseWorkspaceSnapshot(raw: string, currentSource?: WorkspaceSnapshotSource): ParsedWorkspaceSnapshot {
  bounded(raw);
  let document: unknown;
  try { document = JSON.parse(raw); } catch { throw new Error("This file is not valid workspace JSON."); }
  if (!document || typeof document !== "object" || Array.isArray(document)) throw new Error("This file does not contain a workspace.");
  const data = document as Record<string, unknown>;
  let name = "Imported graph", source: WorkspaceSnapshotSource | null = null;
  let workspace: unknown = document;
  if (data.format !== undefined) {
    if (data.format !== SNAPSHOT_FORMAT) throw new Error("This file is not an RDF4J graph workspace.");
    if (data.version !== SNAPSHOT_VERSION || data.workspaceVersion !== WORKSPACE_FORMAT) throw new Error("This workspace file version is not supported.");
    source = parsedSource(data.source);
    if (!source) throw new Error("This workspace file has an invalid source identity.");
    name = snapshotName(data.name as string); workspace = data.workspace;
    if (!workspace || typeof workspace !== "object" || (workspace as Record<string, unknown>).version !== data.workspaceVersion) {
      throw new Error("The workspace content version does not match its file envelope.");
    }
  } else if (data.version !== undefined && data.version !== WORKSPACE_FORMAT && data.version !== 1) {
    throw new Error("This workspace version is not supported.");
  }
  const sameSource = Boolean(source && currentSource && sameValue(source,
    workspaceSnapshotSource(currentSource.basePath, currentSource.repositoryId, currentSource.serverIdentity)));
  // Parse certified identities first, then consistently downgrade all foreign blank references together.
  const payload = parseWorkspacePayload(JSON.stringify(workspace), { repositoryReferences: true });
  if (!payload) throw new Error("The workspace contains invalid or unsupported content.");
  validateNodeTerms(payload);
  const imported = sameSource ? payload : documentScoped(payload);
  // Adding a file namespace can enlarge IDs and references. Check every bound again after that transformation.
  if (!sameSource) prepareWorkspaceSnapshot(imported);
  return { name, source, payload: imported, sameSource };
}

export async function readWorkspaceSnapshotFile(file: Pick<File, "size" | "text">, currentSource?: WorkspaceSnapshotSource) {
  if (!Number.isFinite(file.size) || file.size < 0 || file.size > MAX_WORKSPACE_BYTES) throw new Error("The workspace file is too large: the limit is 64 MB.");
  return parseWorkspaceSnapshot(await file.text(), currentSource);
}

export function snapshotFilename(name: string): string {
  const stem = name.replace(/\.rdf4j-graph\.json$/i, "").replace(/[<>:"/\\|?*\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ").replace(/^[.\s]+|[.\s]+$/g, "").slice(0, 180).trim();
  return `${stem || "graph"}.rdf4j-graph.json`;
}
